            aWandererD = aWandererD ^ (((RotL64(aCross, 47U) + aOrbiterH) + RotL64(aOrbiterD, 23U)) + aWUSaltE[((aIndex + 119U)) & S_SALT1]);
            aWandererA = aWandererA + (((RotL64(aScatter, 39U) + RotL64(aOrbiterK, 56U)) + aOrbiterD) + RotL64(aCarry, 43U));
