            //
            aOrbiterJ = (aOrbiterJ + aOrbiterE) + 0x27B1C158C3ABDD6BULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterJ) ^ 0xED41B52E5A178E4DULL;
            aOrbiterA = RotL64((aOrbiterA * 0x7106C06B68A22E8BULL), 39U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterF) + 0x39870D71CCFDECCBULL) + aOUSaltE[(((511U - aIndex) + 87U)) & S_SALT1];
            aOrbiterC = ((aOrbiterC ^ aOrbiterK) ^ 0x99ED6C9F8E40593BULL) ^ aOUSaltG[((aIndex + 85U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x3AB7772DAF3D29D3ULL), 57U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterC) + 0xF9F6CE55E408C2D6ULL) + aOUSaltC[((aIndex + 23U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterE) ^ 0xC0CE9879F411C553ULL;
