            //
            aOrbiterC = ((aWandererJ + RotL64(aIngress, 50U)) + 0x57A68BB017472BD9ULL) + aOASaltC[(((511U - aIndex) + 141U)) & S_SALT1];
            aOrbiterA = ((aWandererF + RotL64(aPrevious, 39U)) + RotL64(aCarry, 19U)) + 0x3718B0743ABCA2CCULL;
            aOrbiterF = ((aWandererB + RotL64(aScatter, 27U)) + 0x725B11A727AFBF37ULL) + aOASaltD[(((511U - aIndex) + 81U)) & S_SALT1];
            aOrbiterD = (aWandererA + RotL64(aCross, 35U)) + 0xE66B8AD115C93854ULL;
            aOrbiterJ = (aWandererC + RotL64(aScatter, 11U)) + 0xB15393D6B280DF76ULL;
            aOrbiterK = (aWandererD + RotL64(aIngress, 5U)) + 0x137F4253A8EA1427ULL;
            aOrbiterH = (aWandererI + RotL64(aPrevious, 24U)) + 0x6A8897978E191578ULL;
