            aIngress ^= (RotL64(aSoilLaneA[((aIndex + 6786U)) & S_BLOCK1], 19U) ^ RotL64(aLightningLaneB[((S_BLOCK1 - aIndex + 5237U)) & S_BLOCK1], 41U));
