            aScatter = TwistMix64::DiffuseB((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterK = ((aWandererC + RotL64(aScatter, 40U)) + 0x6B69EC81D66B3A8CULL) + aOASaltD[((aIndex + 22U)) & S_SALT1];
            aOrbiterG = (aWandererD + RotL64(aPrevious, 29U)) + 0x2FB7CAB49CD9C7CDULL;
            aOrbiterE = ((aWandererG + RotL64(aCross, 19U)) + 0x6FE29B17338486C0ULL) + aOASaltH[(((511U - aIndex) + 67U)) & S_SALT1];
            aOrbiterH = (aWandererB + RotL64(aIngress, 47U)) + 0x68F9ABBFBBA3B054ULL;
            aOrbiterA = (aWandererA + RotL64(aCross, 3U)) + 0x59DE4C16587C32D6ULL;
            aOrbiterB = (((aWandererI + RotL64(aScatter, 57U)) + RotL64(aCarry, 41U)) + 0xBC35B62EFC232791ULL) + aOASaltG[(((511U - aIndex) + 3U)) & S_SALT1];
            aOrbiterC = ((aWandererK + RotL64(aIngress, 51U)) + 0xAD0885BC88F8EA3AULL) + aOASaltE[((aIndex + 337U)) & S_SALT1];
            aOrbiterF = ((aWandererH + RotL64(aPrevious, 23U)) + RotL64(aCarry, 5U)) + 0x346CFD0A8484AADFULL;
            aOrbiterJ = ((aWandererF + RotL64(aCross, 34U)) + RotL64(aCarry, 53U)) + 0x7D1B5B308F989847ULL;
            //
            aOrbiterK = (aOrbiterK + aOrbiterG) + 0xDA939FB5EE230143ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterK) ^ 0x36FA92DB934EA739ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x838FA0535822955FULL), 29U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterA) + 0x4734CB30B08FD527ULL) + aOUSaltD[(((511U - aIndex) + 93U)) & S_SALT1];
