            aOrbiterK = (aOrbiterK + aOrbiterD) + 0x6B51729C3AE14ACEULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterK) ^ 0xE4B40B70E2D9506FULL;
            aOrbiterA = RotL64((aOrbiterA * 0x99CA19ABE6FC23CBULL), 47U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterH) + 0xAECAD5259F88B020ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterA) ^ 0xCC0CF537B969D794ULL;
            aOrbiterE = RotL64((aOrbiterE * 0xDEC04D0EF0D1534FULL), 5U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterF) + 0x652F6BCBA494598AULL) + aOUSaltC[(((511U - aIndex) + 508U)) & S_SALT1];
            aOrbiterI = ((aOrbiterI ^ aOrbiterG) ^ 0xBD8107237949ECB4ULL) ^ aOUSaltG[((aIndex + 263U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x21066B388384BF9DULL), 53U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterA) + 0x8D8788F91F0AAD31ULL) + aOUSaltD[((aIndex + 441U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterC) ^ 0x67767D2CFB704E51ULL;
