            aOrbiterE = (aOrbiterE + aOrbiterG) + 0xBDA224E923E7AE44ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterE) ^ 0x5F636AED7E16B7B3ULL) ^ aOUSaltF[(((511U - aIndex) + 448U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0xB7D1718BD2921839ULL), 3U);
