            aOrbiterK = (aWandererH + RotL64(aIngress, 35U)) + 0x2F5EE697494B8BCFULL;
            aOrbiterF = (((aWandererF + RotL64(aCross, 27U)) + RotL64(aCarry, 29U)) + 0xA361BB6025F3FB12ULL) + aOASaltH[((aIndex + 178U)) & S_SALT1];
