            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterF = (aWandererB + RotL64(aCross, 47U)) + 0xE3C2B254B4E9451CULL;
            aOrbiterI = ((aWandererK + RotL64(aPrevious, 53U)) + 0x773EA631BC38D9A0ULL) + aOASaltH[(((511U - aIndex) + 224U)) & S_SALT1];
