            aOrbiterG = ((aWandererH + RotL64(aCross, 40U)) + RotL64(aCarry, 23U)) + 0x72D0F9FA10187A0EULL;
            aOrbiterJ = ((aWandererC + RotL64(aPrevious, 27U)) + 0x74C705466B5D9C55ULL) + aOASaltG[((aIndex + 313U)) & S_SALT1];
