            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterF) + 0xA2185540F4264CEAULL) + aOUSaltH[(((511U - aIndex) + 338U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterJ) ^ 0x02681C72D50306FBULL;
            aOrbiterG = RotL64((aOrbiterG * 0x157C29BD86FE4155ULL), 13U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterH) + 0x9A5474EB1966E40BULL) + aOUSaltC[((aIndex + 216U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterG) ^ 0x5890E6FCCCAFABBAULL;
            aOrbiterE = RotL64((aOrbiterE * 0x41D22FE6C9A23F67ULL), 47U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterJ) + 0x6D7D733C49DBA659ULL) + aOUSaltG[((aIndex + 442U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterE) ^ 0xCE5088B80B715809ULL;
