            //
            aOrbiterF = (((aWandererF + RotL64(aCross, 27U)) + RotL64(aCarry, 27U)) + 0xF9C27A6F3E5FCE7AULL) + aOASaltD[(((511U - aIndex) + 434U)) & S_SALT1];
