            aOrbiterD = RotL64((aOrbiterD * 0xBBF564263A0CA25DULL), 5U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterK) + 0x36E4D340ECCEF87AULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterE) ^ 0x0A4753B1A114A348ULL) ^ aOUSaltF[((aIndex + 245U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x107A2D5C57DE498BULL), 37U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterE) + 0xFD0E5236B94F188DULL;
